using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.UI;
using Floor33;

public class MainControl : MonoBehaviour {
 [SerializeField] private InputField m_nControlCountInputField,m_nControlLightCountInputField,m_timeIntervalInputField;
 Game game;Settings config;Network network;string folder,name="",player="",notice="";int selectedGameMode=2;int selectedDuration=30;int difficulty=0,tab,selected=0;bool simulation=true,autoDemo,saved,wasPaused;
 bool floorStartRequested;float demoAt,feedbackAt;string feedback="";
 GUIStyle heading,label,tiny,button,input,number;Text boardTitle,boardName,boardScore,boardTime,boardHint,boardRank,rulesTitle,rulesBody,rulesFooter;
 [Serializable] public class Entry { public string name,date,mode;public int score,hits,errors,difficulty,uniqueTiles,durationSeconds,gameType,remainingLives; public int[] tileTouches; }
 [Serializable] public class Ranking { public List<Entry> entries=new List<Entry>(); }
 Ranking ranking=new Ranking();bool showSimulationRanks=true;Texture2D mapTexture;
 string ConfigPath { get{return Path.Combine(folder,"FloorConfig.json");} }
 void Awake(){Application.runInBackground=true;Application.targetFrameRate=60;folder=Path.GetDirectoryName(Application.dataPath);
  foreach(Canvas c in FindObjectsOfType<Canvas>())c.enabled=false;
  config=new Settings();try{if(File.Exists(ConfigPath))config=JsonUtility.FromJson<Settings>(File.ReadAllText(ConfigPath));else File.WriteAllText(ConfigPath,JsonUtility.ToJson(config,true));if(config==null||config.receiverWireIds==null||config.receiverWireIds.Length!=1||config.controllerWireIds==null||config.controllerWireIds.Length!=1)throw new Exception("One receiver ID and one controller ID required");}catch(Exception e){config=new Settings();notice="Config error: "+e.Message;}
  simulation=!config.hardwareEnabled;showSimulationRanks=simulation;game=new Game(Environment.TickCount);network=new Network(config);mapTexture=new Texture2D(Layout.Width,Layout.Height,TextureFormat.RGBA32,false);mapTexture.filterMode=FilterMode.Point;
  try{string p=Path.Combine(folder,"LeaderboardTouchCounter.json");if(File.Exists(p))ranking=JsonUtility.FromJson<Ranking>(File.ReadAllText(p))??new Ranking();if(ranking.entries==null)ranking.entries=new List<Entry>();}catch(Exception e){notice="Leaderboard: "+e.Message;}
  SetupBoard();Debug.Log("Floor33 READY | 396 tiles | 6 chains | mode="+(simulation?"SIMULATION":"HARDWARE"));
  if(Array.IndexOf(Environment.GetCommandLineArgs(),"--demo")>=0){name="DEMO PLAYER";autoDemo=true;StartGame();}
 }
 string ModeName(){return selectedGameMode==2?"RANDOM WAVES":selectedGameMode==1?"COLOUR RUSH":"TOUCH COUNTER";}
 string RulesText(){return selectedGameMode==2?"8 SINGLE GREEN TILES - MOVE EVERY 5 SECONDS\n\nRED WAVES MOVE ACROSS PARTS OF THE FLOOR\nORANGE IS THE WARNING EDGE AHEAD OF THEM\nBLUE: TRAVEL    GREEN: CURRENT SAFE TILE\n\nWaves enter from random sides at different times.\nEach green tile relocates one step every 5 seconds.\nOld safe tiles briefly warn orange so you can move.\n\nBe on green at each 9-second checkpoint: +5.\nLava hit or missed checkpoint: -2 and 1 life.\nDamage has a 1-second cooldown.\n\n3 lives. Choose 30, 60 or 90 seconds.":selectedGameMode==1?
  "START AT THE SHORT END, NEAR COLUMN 1\n\nBLUE TARGET  +1     PURPLE BONUS  +3\n\nEVERY 5 TARGETS: EXTRA +3 COMBO BONUS\nRED HAZARD: -2 AND COMBO RESETS\nGREEN: SAFE TO STAND OR TRAVEL\n\nTargets advance 4 columns at a time along the\n33-tile length. Follow the green centre route.\nPatterns refresh every 7 to 4 seconds.\n\nStep off before pressing a target again.\nScore as much as possible before time runs out.":
  "TOUCH ANY TILE TO CHANGE ITS COLOUR\n\nBLUE > GREEN > PURPLE > ORANGE > BLUE\n\nEach new press adds 1 to your total.\nYour individual tile counts are tracked too.\n\nHolding a tile counts once.\nStep off and press again for another touch.\n\nScore as many touches as possible before time ends.";}
 GameObject ScreenRoot(int display,string title){Display.displays[display].Activate();GameObject root=new GameObject(title);Canvas c=root.AddComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;c.targetDisplay=display;CanvasScaler sc=root.AddComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);GameObject bg=new GameObject("Background");bg.transform.SetParent(root.transform,false);Image im=bg.AddComponent<Image>();im.color=new Color(.025f,.04f,.075f);RectTransform rt=im.rectTransform;rt.anchorMin=Vector2.zero;rt.anchorMax=Vector2.one;rt.offsetMin=rt.offsetMax=Vector2.zero;return root;}
 void SetupBoard(){Debug.Log("Floor displays detected: "+Display.displays.Length);
  if(Display.displays.Length>=2){GameObject root=ScreenRoot(1,"Display 2 Leaderboard");boardTitle=Text(root,"LEADERBOARD",64,435,100);boardName=Text(root,"",36,325,80);boardRank=Text(root,"",40,-15,560);boardRank.alignment=TextAnchor.UpperCenter;boardTime=Text(root,"",32,-360,90);boardHint=Text(root,"REGISTER ON DISPLAY 1",30,-440,70);}
  if(Display.displays.Length>=3){GameObject root=ScreenRoot(2,"Display 3 Rules");rulesTitle=Text(root,"",64,435,100);rulesBody=Text(root,"",38,-10,740);rulesFooter=Text(root,"",30,-440,70);}
  if(Display.displays.Length<3)notice="Detected "+Display.displays.Length+" display(s). Display 1: player / score. Connect Display 2: leaderboard, Display 3: rules. Rules preview is on this screen.";
 }
 Text Text(GameObject root,string s,int size,float y,float h){GameObject o=new GameObject(s);o.transform.SetParent(root.transform,false);Text t=o.AddComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("Arial.ttf");t.supportRichText=false;t.fontSize=size;t.alignment=TextAnchor.MiddleCenter;t.color=Color.white;t.text=s;RectTransform r=t.rectTransform;r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.anchoredPosition=new Vector2(0,y);r.sizeDelta=new Vector2(1720,h);return t;}
 void StartGame(){if(name.Trim().Length==0)return;if(!simulation&&!network.Healthy(Time.realtimeSinceStartup)){notice="The receiver must respond before starting. Open Mapping / Network.";return;}player=name.Trim();game.Start(difficulty,selectedDuration,selectedGameMode);saved=false;tab=0;showSimulationRanks=simulation;feedback="";demoAt=Time.unscaledTime;Debug.Log("Floor33 START "+(simulation?"SIM":"LIVE")+" difficulty="+difficulty);}
 void OnTouch(int i,bool down){if(tab!=2&&game.StartPressed(i,down)){game.Touch(i,down);if(name.Trim().Length>0)floorStartRequested=true;else notice="Register your name on Display 1, then step on the green START letters.";return;}int delta=game.Touch(i,down);if(delta!=0){feedback=game.Feedback;feedbackAt=Time.unscaledTime;Debug.Log("Floor33 "+feedback+" tile="+i+" score="+game.Score);}if(down&&tab==2)selected=i;}
 void Update(){float now=Time.realtimeSinceStartup;if(!game.Active)game.ShowIdleStart();
  network.Update(now,game.Cells,true,tab==2?selected:-1,OnTouch,game.Active&&game.GameMode==1);if(floorStartRequested){floorStartRequested=false;StartGame();}
  game.Paused=!simulation&&game.Active&&!network.Healthy(now);
  if(game.Paused&&!wasPaused)Debug.LogWarning("Floor33 PAUSED - receiver data lost; timer frozen");wasPaused=game.Paused;
  int beforeTick=game.Score;game.Tick(Time.unscaledDeltaTime);if(game.Score!=beforeTick){feedback=game.Feedback;feedbackAt=Time.unscaledTime;Debug.Log("RunToGreen: "+feedback+" score="+game.Score);}
  if(simulation&&autoDemo&&game.Active&&game.Countdown<=0&&Time.unscaledTime>=demoAt){demoAt=Time.unscaledTime+.45f;int target=-1;for(int i=0;i<396;i++)if(game.GameMode==0?i==(game.Hits*37)%396:game.GameMode==2?game.Cells[i]==Cell.Safe:game.Cells[i]==Cell.Blue||game.Cells[i]==Cell.Purple){target=i;break;}if(target>=0){for(int i=0;i<396;i++)if(game.Held[i])OnTouch(i,false);OnTouch(target,true);}}
  if(game.Finished&&!saved){saved=true;ranking.entries.Add(new Entry{name=player,score=game.Score,hits=game.Hits,errors=game.Errors,difficulty=difficulty,uniqueTiles=game.UniqueTouched,remainingLives=game.Lives,gameType=game.GameMode==2?7:game.GameMode,durationSeconds=game.DurationSeconds,tileTouches=(int[])game.TouchCounts.Clone(),mode=simulation?"SIM":"LIVE",date=DateTime.Now.ToString("s")});ranking.entries.Sort(delegate(Entry a,Entry b){return b.score.CompareTo(a.score);});try{File.WriteAllText(Path.Combine(folder,"LeaderboardTouchCounter.json"),JsonUtility.ToJson(ranking,true));}catch(Exception e){notice="Could not save results: "+e.Message;}Debug.Log("Floor33 GAME OVER score="+game.Score+" hits="+game.Hits+" errors="+game.Errors);name="";autoDemo=false;}
  var pixels=new Color32[396];for(int y=0;y<Layout.Height;y++)for(int x=0;x<33;x++){int i=y*33+x;Color32 c=CellColor(game.Cells[i]);if(tab==2)c=i==selected?new Color32(255,255,255,255):new Color32(18,37,61,255);pixels[(Layout.Height-1-y)*33+x]=c;}mapTexture.SetPixels32(pixels);mapTexture.Apply(false);UpdateBoard();
  if(Input.GetKeyDown(KeyCode.Escape))Application.Quit();
 }
 Color32 CellColor(Cell c){if(c==Cell.Off)return new Color32(3,10,17,255);if(c==Cell.Purple)return new Color32(195,75,255,255);if(c==Cell.Orange)return new Color32(255,155,30,255);return c==Cell.Blue?new Color32(44,124,255,255):c==Cell.Red?new Color32(245,67,88,255):c==Cell.Cleared?new Color32(59,247,164,255):new Color32(35,235,110,255);}
 string RankText(){string s="RANK     PLAYER                   SCORE\n\n";int n=0;foreach(Entry e in ranking.entries){if(e.mode!=(showSimulationRanks?"SIM":"LIVE")||e.difficulty!=difficulty||e.durationSeconds!=selectedDuration||e.gameType!=(selectedGameMode==2?7:selectedGameMode))continue;s+=(++n).ToString("00")+"      "+e.name+"       "+e.score+"\n";if(n==7)break;}return n==0?"No results yet":s;}
 void UpdateBoard(){
  if(boardTitle!=null){boardName.text=ModeName()+"  /  "+selectedDuration+" SECONDS  /  "+(simulation?"SIMULATION":"PHYSICAL FLOOR");boardRank.text=RankText();boardTime.text=game.Active?"PLAYING: "+player+"  |  SCORE "+game.Score:game.Finished?player+"  |  FINAL SCORE "+game.Score:"NEXT PLAYER: REGISTER ON DISPLAY 1";}
  if(rulesTitle!=null){rulesTitle.text=ModeName()+" / HOW TO PLAY";rulesBody.text=RulesText();rulesFooter.text=selectedDuration+" SECONDS  |  33 x 12 TILES  |  3 SECOND PREPARATION";}
 }
 void Styles(){if(heading!=null)return;heading=new GUIStyle(GUI.skin.label){fontSize=32,fontStyle=FontStyle.Bold};heading.normal.textColor=Color.white;label=new GUIStyle(heading){fontSize=18,fontStyle=FontStyle.Normal,wordWrap=true};tiny=new GUIStyle(label){fontSize=14};number=new GUIStyle(heading){fontSize=68};button=new GUIStyle(GUI.skin.button){fontSize=15};input=new GUIStyle(GUI.skin.textField){fontSize=24};}
 void Box(float x,float y,float w,float h,Color c){GUI.color=c;GUI.DrawTexture(new Rect(x,y,w,h),Texture2D.whiteTexture);GUI.color=Color.white;}
 bool Button(float x,float y,float w,string s){return GUI.Button(new Rect(x,y,w,42),s,button);}
 void OnGUI(){Styles();float uiScale=Mathf.Min(Screen.width/1280f,Screen.height/800f);GUI.matrix=Matrix4x4.TRS(new Vector3((Screen.width-1280*uiScale)/2,(Screen.height-800*uiScale)/2,0),Quaternion.identity,new Vector3(uiScale,uiScale,1));Box(0,0,1280,800,new Color(.025f,.04f,.075f));
  GUI.Label(new Rect(30,18,850,48),ModeName()+"     33 x 12 ARENA",heading);GUI.Label(new Rect(30,67,1200,28),"396 TILES   /   33 x 12 GRID   /   6 CHAINS   /   30 / 60 / 90 SECONDS",tiny);
  GUI.color=simulation?new Color(.45f,.75f,1):new Color(.3f,1,.65f);GUI.Label(new Rect(860,28,390,35),simulation?"SIMULATION - CLICK TO STEP":"PHYSICAL FLOOR",label);GUI.color=Color.white;
  for(int i=0;i<4;i++)if(Button(30+i*150,104,140,new string[]{"PLAYER / SCORE","LEADERBOARD","MAPPING","RULES"}[i])){tab=i;if(i==2&&game.Active){game.Stop();autoDemo=false;notice="Session cancelled for mapping check.";}}
  GUI.Label(new Rect(650,112,600,45),network.Status,tiny);
  if(tab==0)DrawPlay();else if(tab==1)DrawScore();else if(tab==2)DrawMapping();else{GUI.Label(new Rect(50,180,1100,70),ModeName()+" / RULES",heading);GUI.Label(new Rect(50,260,1140,470),RulesText(),label);}
  if(notice.Length>0)GUI.Label(new Rect(30,754,1210,40),notice,tiny);
 }
 void DrawPlay(){Box(30,165,380,565,new Color(.045f,.075f,.12f));GUI.enabled=!game.Active;for(int mode=0;mode<3;mode++){int choice=new int[]{2,1,0}[mode];GUI.backgroundColor=selectedGameMode==choice?new Color(.2f,.8f,.7f):Color.white;if(Button(455+mode*185,185,180,new string[]{"RANDOM WAVES","COLOUR RUSH","TOUCH COUNTER"}[mode]))selectedGameMode=choice;}GUI.backgroundColor=Color.white;GUI.enabled=true;
  if(!game.Active){GUI.Label(new Rect(52,185,330,48),game.Finished?"TIME UP":"PLAYER REGISTRATION",label);if(game.Finished)GUI.Label(new Rect(52,230,330,90),game.Score+" POINTS",heading);
   GUI.Label(new Rect(52,game.Finished?315:250,330,28),"PLAYER NAME",tiny);name=GUI.TextField(new Rect(52,game.Finished?350:285,330,50),name,24,input);
   float y=game.Finished?420:360;GUI.Label(new Rect(52,y,330,28),"GAME DURATION",tiny);for(int i=0;i<3;i++){int duration=(i+1)*30;GUI.backgroundColor=duration==selectedDuration?new Color(.25f,.8f,.6f):Color.white;if(Button(52+i*110,y+35,104,duration+" SEC"))selectedDuration=duration;}GUI.backgroundColor=Color.white;
   GUI.Label(new Rect(52,y+87,330,36),"Selected: "+selectedDuration+" seconds",label);
   GUI.enabled=name.Trim().Length>0;if(Button(52,y+145,330,"START "+selectedDuration+"-SECOND GAME"))StartGame();GUI.enabled=true;GUI.Label(new Rect(52,y+196,330,45),"Or step on the green START letters after registering.",tiny);
  }else{GUI.Label(new Rect(52,185,330,45),player,heading);GUI.Label(new Rect(52,245,330,95),game.Score.ToString(),number);GUI.Label(new Rect(52,350,330,80),game.Paused?"CONNECTION LOST\nTIMER PAUSED":game.Countdown>0?"READY  "+Math.Ceiling(game.Countdown):Math.Ceiling(game.SecondsLeft)+" SECONDS",heading);GUI.Label(new Rect(52,445,330,70),game.GameMode==2?"LIVES "+game.Lives+" / 3    ROUND "+game.Wave+"\n"+(game.LavaResting?"SAFE - NEXT WAVE":game.LavaActive?game.WaveLabel:Math.Ceiling(game.StageSeconds)+"s UNTIL WAVES"):game.GameMode==0?"TOUCHES "+game.Score+" / UNIQUE "+game.UniqueTouched:"STAGE "+game.Wave+"  TARGETS "+game.Targets+"\nCOMBO "+game.Combo+" / BEST "+game.BestCombo,label);GUI.Label(new Rect(52,535,330,70),game.Feedback,label);if(Button(52,650,330,"END / NEXT PLAYER")){game.Stop();player="";autoDemo=false;}}
  DrawMap(new Rect(455,250,550,550f*12/33));GUI.Label(new Rect(455,480,550,250),RulesText(),tiny);
  GUI.Label(new Rect(1030,185,220,180),selectedGameMode==2?"RANDOM WAVES\n\n8 SAFE TILES\nSURVIVE +5\nLAVA HIT -2":selectedGameMode==1?"COLOUR RUSH\n\nBLUE +1\nPURPLE +3\nRED -2\n5 HIT COMBO +3":"TOUCH COUNTER\n\nTOUCH ANY TILE\nCHANGE COLOUR\nCOUNT +1",label);GUI.Label(new Rect(1030,410,220,180),selectedGameMode==2?"Random lava bands keep moving. The 8 single green tiles change every 5 seconds. Follow green and watch the relocation countdown.":selectedGameMode==1?"Follow targets along the 33-tile length. Green is safe. Red resets your combo. Patterns get faster as you progress.":"Blue > Green > Purple > Orange. Each new press adds one touch. Step off before pressing the same tile again.",label);
  if(simulation){GUI.Label(new Rect(1030,595,210,60),"Simulation: click a tile to stand there; click another tile to move.",tiny);if(Button(1030,675,200,autoDemo?"STOP AUTO DEMO":"AUTO DEMO")){if(game.Active)autoDemo=!autoDemo;else{name="DEMO PLAYER";autoDemo=true;StartGame();}}}
 }
 void DrawMap(Rect r){GUI.DrawTexture(r,mapTexture);float step=r.width/33;if(tab!=2){GUIStyle countStyle=new GUIStyle(tiny){fontSize=10,alignment=TextAnchor.MiddleCenter};for(int i=0;i<396;i++)if(game.Active&&game.GameMode==0&&game.TouchCounts[i]>0)GUI.Label(new Rect(r.x+(i%33)*step,r.y+(i/33)*step,step,step),game.TouchCounts[i].ToString(),countStyle);}GUI.color=new Color(.03f,.05f,.08f,.6f);for(int i=0;i<=Layout.Width;i++)GUI.DrawTexture(new Rect(r.x+i*step,r.y,1,r.height),Texture2D.whiteTexture);for(int i=0;i<=Layout.Height;i++)GUI.DrawTexture(new Rect(r.x,r.y+i*step,r.width,1),Texture2D.whiteTexture);GUI.color=Color.white;
  if(r.Contains(Event.current.mousePosition)&&Event.current.type==EventType.MouseDown){int x=Mathf.Clamp((int)((Event.current.mousePosition.x-r.x)/step),0,32),y=Mathf.Clamp((int)((Event.current.mousePosition.y-r.y)/step),0,Layout.Height-1),i=y*33+x;if(tab==2)selected=i;else if(simulation){for(int k=0;k<396;k++)if(game.Held[k])OnTouch(k,false);OnTouch(i,true);}Event.current.Use();}
 }
 void DrawScore(){GUI.Label(new Rect(50,180,800,50),game.Finished?"SESSION COMPLETE":"LIVE SCORE",heading);GUI.Label(new Rect(50,245,500,50),player,label);GUI.Label(new Rect(50,310,500,100),game.Score.ToString(),number);GUI.Label(new Rect(50,430,500,120),"TIME LEFT  "+Math.Ceiling(game.SecondsLeft)+"s\nTOUCHES  "+game.Score+"    UNIQUE TILES  "+game.UniqueTouched,label);GUI.Label(new Rect(640,180,590,50),(showSimulationRanks?"SIMULATION":"PHYSICAL")+" / "+selectedDuration+"s LEADERBOARD",heading);GUI.Label(new Rect(640,260,590,390),RankText(),label);if(Button(640,680,270,"SWITCH LEADERBOARD"))showSimulationRanks=!showSimulationRanks;}
 void DrawMapping(){DrawMap(new Rect(30,250,550,550f*12/33));Address a=Layout.At(selected);GUI.Label(new Rect(620,175,620,48),"TILE / CONNECTION CHECK",heading);GUI.Label(new Rect(620,238,600,130),"ROW "+(selected/33+1)+"    COLUMN "+(selected%33+1)+"\nCHAIN P"+a.Chain+"    CONTROLLER "+a.Controller+"    PORT "+a.Port+"\nPOSITION "+a.Position+" / "+Layout.MaxPerPort,label);
  if(Button(620,380,170,"PREVIOUS TILE"))selected=(selected+395)%396;if(Button(805,380,170,"NEXT TILE"))selected=(selected+1)%396;if(Button(990,380,240,"NEXT CHAIN")){int chain=a.Chain%Layout.ChainCount;selected=Layout.Index(chain/8+1,chain%8+1,1);}
  GUI.Label(new Rect(620,450,610,150),network.Status+"\n"+network.LastPacket+"\nRX "+network.Received+"   TX "+network.Sent+"\n"+(simulation?"Physical output is off. Click any tile to inspect its CAD address.":"Selected tile is white; other tiles are off. Touch a physical tile to inspect its address."),label);
  GUI.Label(new Rect(620,620,610,125),"33 x 12 = 396 tiles. P1-P6 = 66 each. Controller 1 ports 7-8 unused.\nLive setup: FloorConfig.json. Confirm the receiver ID and scan all chain boundaries before enabling play.\nOnly one controller and receiver are required for this layout.",tiny);
 }
 void OnApplicationQuit(){if(network!=null){network.Update(Time.realtimeSinceStartup+1,game.Cells,false,-1,delegate(int i,bool b){});network.Dispose();}}
}
